#include <deque>
#include <iostream>

int main() {
    std::deque<int> d = {10, 20, 30, 40};

    // Case 1: Iterators remain valid for elements not moved
    auto it_20 = d.begin() + 1;
    d.push_front(5); // Insert at front
    // it_20 is still valid and points to 20
    std::cout << "Front insert: " << *it_20 << "\n"; 

    // Case 2: Middle insertion invalidates everything
    auto ref_40 = &d.back(); // Pointer to 40

    // Insert 25 at index 3 (middle operation)
    d.insert(d.begin() + 3, 25);

    // *ref_40; // DANGER: UNDEFINED BEHAVIOR! ref_40 is invalidated.

    // Correct way: Re-obtain iterator/pointer
    auto new_ref_40 = &d.back();
    std::cout << "Middle insert: " << *new_ref_40 << "\n"; 
}
